def evaluate(input_data):
    stack = []
    words = {}

    def compile_token(token):
        """Compile one token into an action, resolving words against the
        dictionary as it stands at definition time."""
        if NUMBER_RE.fullmatch(token):
            return ("num", int(token))
        name = token.lower()
        if name in words:
            return ("word", words[name])
        if name in BUILTINS:
            return ("builtin", BUILTINS[name])
        raise ValueError("undefined operation")

    def exec_actions(actions):
        for action in actions:
            kind = action[0]
            if kind == "num":
                stack.append(action[1])
            elif kind == "word":
                exec_actions(action[1])
            else:
                action[1](stack)

    for line in input_data:
        tokens = line.split()
        i = 0
        while i < len(tokens):
            if tokens[i] == ":":
                i += 1
                name = tokens[i].lower()
                if NUMBER_RE.fullmatch(name):
                    raise ValueError("illegal operation")
                i += 1
                body = []
                while tokens[i] != ";":
                    body.append(compile_token(tokens[i]))
                    i += 1
                words[name] = body
                i += 1  # skip the terminating ";"
            else:
                exec_actions([compile_token(tokens[i])])
                i += 1

    return stack
